def re_arrange(arr, n):
    pos = []
    neg = []
    for i in range(n):
        if arr[i] >= 0:
            pos.append(arr[i])
        else:
            neg.append(arr[i])

    pos.sort()
    neg.sort()

    j = 0
    k = 0
    for i in range(n):
        if i % 2 == 0:
            if j < len(pos):
                arr[i] = pos[j]
                j += 1
            else:
                arr[i] = neg[k]
                k += 1
        else:
            if k < len(neg):
                arr[i] = neg[k]
                k += 1
            else:
                arr[i] = pos[j]
                j += 1

    return arr

